mapper.sql:
WHERE s.deleted = FALSE

    AND (s.session_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR s.session_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR p.plan_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR EXISTS (SELECT 1 FROM biz_course c
                  WHERE c.id = s.course_id AND c.deleted = FALSE
                    AND c.course_name ILIKE #{q.keywordLike} ESCAPE '\')
      OR EXISTS (SELECT 1 FROM biz_lecturer l
                  WHERE l.id = s.lecturer_id AND l.deleted = FALSE
                    AND l.lecturer_name ILIKE #{q.keywordLike} ESCAPE '\')
      OR EXISTS (SELECT 1 FROM org_employee e
                  WHERE e.employee_no = p.owner_no AND e.deleted = FALSE
                    AND e.employee_name ILIKE #{q.keywordLike} ESCAPE '\'))


    AND s.plan_id = #{q.planId}


    AND s.course_id = #{q.courseId}


    AND s.lecturer_id = #{q.lecturerId}


    AND s.session_state = #{q.sessionState}


    AND p.plan_state = #{q.planState}




            AND s.session_state = #{q.archivedState}


            AND s.session_state <> #{q.archivedState}




    AND s.training_form = #{q.trainingForm}


    AND s.training_date >= #{q.dateFrom}


    AND s.training_date <= #{q.dateTo}




            AND EXISTS (SELECT 1 FROM dtl_attendance a
                         WHERE a.session_id = s.id AND a.deleted = FALSE)


            AND NOT EXISTS (SELECT 1 FROM dtl_attendance a
                             WHERE a.session_id = s.id AND a.deleted = FALSE)
